// src/lib/middlewares/not-found-middleware.ts
function createNotFoundHandler(config5 = {}) {
  const { enableLogging = true, customMessage } = config5;
  return (c) => {
    const requestedPath = c.req.path;
    const method = c.req.method;
    const requestId2 = c.get("requestId");
    if (enableLogging) {
      console.warn(`[404] ${method} ${requestedPath}`, {
        requestId: requestId2,
        userAgent: c.req.header("user-agent")
      });
    }
    const message = customMessage || `The requested resource '${requestedPath}' was not found`;
    return c.json(HONO_ERROR("NOT_FOUND", message, { requestId: requestId2 }), 404);
  };
}
var notFoundHandler2 = createNotFoundHandler();
var apiNotFoundHandler = createNotFoundHandler({
  customMessage: "API endpoint not found. Please check the documentation for available endpoints."
});

// src/lib/middlewares/favicon-middleware.ts
function faviconMiddleware(emoji3) {
  const svgContent = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">
    <text y=".9em" font-size="90">${emoji3}</text>
  </svg>`;
  return async (c, next) => {
    if (c.req.path === "/favicon.ico" || c.req.path === "/favicon") {
      c.header("Content-Type", "image/svg+xml");
      c.header("Cache-Control", "public, max-age=3600");
      return c.body(svgContent);
    }
    return next();
  };
}

