function hasRequiredRole(userRole, requiredRole) {
  const roleHierarchy = {
    user: 0,
    writer: 1,
    sales: 2,
    admin: 3,
    "super-admin": 4
  };
  const userLevel = roleHierarchy[userRole] ?? -1;
  const requiredLevel = roleHierarchy[requiredRole] ?? 999;
  return userLevel >= requiredLevel;
}
