var GET_MyRole_Handler = async (c) => {
  try {
    const user2 = c.get("user");
    const permissions = {
      canManageUsers: ["super-admin", "admin"].includes(user2.role),
      canManageRoles: user2.role === "super-admin",
      canAccessSales: ["super-admin", "admin", "sales"].includes(user2.role),
      canWrite: ["super-admin", "admin", "sales", "writer"].includes(user2.role)
    };
    return c.json(HONO_RESPONSE({
      message: "Role information retrieved successfully",
      data: {
        role: user2.role,
        permissions
      }
    }), HTTP.OK);
  } catch (error49) {
    return c.json(HONO_ERROR("INTERNAL_SERVER_ERROR", "Failed to retrieve role information", {
      issues: [
        {
          message: error49 instanceof Error ? error49.message : "Unknown error occurred"
        }
      ]
    }), HTTP.INTERNAL_SERVER_ERROR);
  }
};
