// src/index.ts
init_auth();
initializeSentry();
var createApp = () => {
  const app = createRouter().basePath("/api");
  app.use(requestId()).use(faviconMiddleware("\uD83D\uDCDD"));
  app.use(logger2(HonoLogger));
  app.use("/*", cors({
    origin: env_default.NODE_ENV === "development" ? ["http://localhost:3000", "http://localhost:9999"] : [env_default.BETTER_AUTH_URL],
    credentials: true,
    allowHeaders: ["Content-Type", "Authorization"],
    allowMethods: ["POST", "GET", "OPTIONS"],
    exposeHeaders: ["Content-Length"],
    maxAge: 600
  }));
  app.use("*", sentryMiddleware);
  app.notFound(createNotFoundHandler());
  app.onError(sentryErrorHandler(onError));
  return app;
};
var app = createApp();
configureOpenAPI(app);
app.on(["POST", "GET"], "/api/auth/*", (c) => {
  return auth.handler(c.req.raw);
});
app.openapi({
  path: "/",
  method: "get",
  tags: ["Base"],
  responses: {
    [HTTP.OK]: APISchema.OK,
    [HTTP.UNPROCESSABLE_ENTITY]: APISchema.UNPROCESSABLE_ENTITY
  }
}, (c) => {
  return c.json(HONO_RESPONSE({ message: "Yollo Bozo" }), HTTP.OK);
});
var controllers = [mailerController, userController, authController];
for (const controller of controllers) {
  app.route("/", controller);
}
serve({
  port: env_default.PORT,
  fetch: app.fetch
});
HonoLogger(`\uD83D\uDE80 Server running in ${env_default.NODE_ENV} mode on port ${env_default.PORT}`);
HonoLogger(`\uD83D\uDCDA Scalar API documentation available at: http://localhost:${env_default.PORT}/api/reference`);
export {
  app
};
